\begin{equation*}
-P(0)=\rho g e\;\;\Longleftrightarrow\;\;
2\mu k a_{2}=\rho g e ,
\qquad a_{2}=\frac{\rho g}{2\mu k}\,e ,           \tag{1}
\end{equation*}
