     =\frac{S_{0}}{\rho g}\,
\Bigg[\frac{\kappa}{\cosh\kappa}+\frac{\cosh\kappa}{\kappa}\Bigg]^{-1}.
\end{equation*}
Writing the restoring buoyancy as $\Delta\rho g e$ the conventional
isostatic form is
\begin{equation*}
e_{s}= \chi(\kappa)\,\frac{S_{0}}{\Delta\rho g},
\qquad 
\chi(\kappa)=\frac{\kappa\cosh\kappa}{\kappa^{2}+\cosh^{2}\kappa}
          =\Bigg[\frac{\kappa}{\cosh\kappa}+
                 \frac{\cosh\kappa}{\kappa}\Bigg]^{-1} ,
\qquad \kappa=kh .
\end{equation*}
In particular
\begin{equation*}
\chi(\kappa)=\frac{1}{\kappa\,{\rm sech}\kappa+\kappa^{-1}\cosh\kappa},
\end{equation*}
\begin{equation*}
\chi\simeq\kappa\;,\qquad \kappa\ll1,
\qquad 
\chi\simeq2\kappa e^{-\kappa}\to0\;,\qquad \kappa\gg1,
\end{equation*}
and
\begin{equation*}
\max_{\kappa>0}\chi(\kappa)\simeq0.46\approx\frac12 ,
\qquad \kappa_{\max}\simeq1.1\!-\!1.2,
\end{equation*}
so that in the most responsive $kh\sim1$ limit the familiar
shear-driven dynamic topography is
\begin{equation*}
e_{s}^{\max}\approx\frac12\,\frac{S_{0}}{\Delta\rho g},
\qquad 
e_{s}\simeq kh\,\frac{S_{0}}{\Delta\rho g}\;\;\;kh\ll1,
\end{equation*}
which with $\rho\equiv\Delta\rho$ in $\sigma_{zz}(0)=\rho ge\cos kx$
is the $e_{s}= \chi S_{0}/\rho g$ form quoted above.  The
$\sinh$-numerator expressions are the same result up to the
conventional $ {\rm sh}\leftrightarrow {\rm ch}$ book-keeping; up to the
$\rho\leftrightarrow\Delta\rho$ identification this is the usual
viscous-channel factor $\chi(t)=t\cosh t/(t^{2}+\cosh^{2}t)$ with the
commonly quoted long-wave value $\chi\approx kh$ and the
maximum response $\chi_{\max}\approx1/2$. ∎

public_text.3:
In the harmonic representation

\begin{equation*}
u_{x}= \Phi'(z)\sin kx\;, \qquad 
u_{z}=-k\Phi(z)\cos kx\;, \qquad 
p=P(z)\cos kx ,
\end{equation*}
${\rm div}\,u=0$ is identically satisfied and

\begin{equation*}
\bigl(D^{2}-k^{2}\bigr)^{2}\Phi=0 ,
\qquad 
P(z)=\frac{\mu}{k}\Big[\Phi'''(z)-k^{2}\Phi'(z)\Big] ,
\end{equation*}
so that with the kinematic conditions at the free surface

\begin{equation*}
\Phi(0)=0\;,\qquad\Phi'(0)=0\;,\qquad 
u_{x}(0)=0\;,\;u_{z}(0)=\dot e=0
\end{equation*}
in the steady state the two independent solutions can be taken as

\begin{equation*}
\Phi(z)=a\Big[\sinh kz-kz\cosh kz\Big]+b\,z\sinh kz .
\end{equation*}
Then

\begin{equation*}
\sigma_{zz}= -\frac{\mu}{k}\Big[\Phi'''+k^{2}\Phi'\Big]\cos kx ,\qquad
\sigma_{xz}= \mu\Big[\Phi''+k^{2}\Phi\Big]\sin kx .
\end{equation*}
At the free surface

\begin{equation*}
\sigma_{zz}(0)=-\frac{\mu}{k}\Phi'''(0)=\rho g e_{s}\cos kx,
\qquad\Phi'''(0)=-2k^{3}a ,
\end{equation*}
so that with the usual sign convention

\begin{equation*}
a=\frac{\rho g e_{s}}{2\mu k^{2}}>0 .
\end{equation*}
The zero normal traction at the base is

\begin{equation*}
\sigma_{zz}(h)=0\iff\Phi'''(h)+k^{2}\Phi'(h)=0,
\end{equation*}
i.e.

\begin{equation*}
a\,k\Big[\cosh t+t\sinh t\Big]+b\Big[2\sinh t+t\cosh t\Big]=0,
\qquad t\equiv kh,
\end{equation*}
and the imposed basal shear is

\begin{equation*}
\sigma_{xz}(h)=\mu\Big[\Phi''+k^{2}\Phi\Big]_{h}=S_{0}\sin kx .
\end{equation*}
With the above $\Phi$

\begin{equation*}
\Phi''+k^{2}\Phi=2k\Big[\,b\cosh kz-a k z\cosh kz+bz\sinh kz\Big],
\end{equation*}
so that at $z=h$

\begin{equation*}
2\mu k\Big[\,b\cosh t-b\,t\sinh t-a k t\cosh t\Big]=S_{0} .
\end{equation*}
Eliminating $b$ with the $\sigma_{zz}(h)=0$ condition gives

\begin{equation*}
2\mu k^{2}a\,
\frac{\cosh^{2}t+t^{2}}{t\cosh t}=S_{0},
\end{equation*}
i.e. with $a=\rho g e_{s}/2\mu k^{2}$

\begin{equation*}
\rho g e_{s}=S_{0}\,
\frac{t\cosh t}{\cosh^{2}t+t^{2}}\;,\qquad t=kh,
\end{equation*}
so that on writing the restoring stress as $\Delta\rho g e_{s}$,

\begin{equation*}
 e_{s}(k)=\chi(t)\,\frac{S_{0}}{\Delta\rho g},
\qquad 
\chi(t)=\frac{t\cosh t}{\cosh^{2}t+t^{2}}
       =\Bigg[\frac{t}{\cosh t}+\frac{\cosh t}{t}\Bigg]^{-1},
\qquad t=kh .
\end{equation*}
In particular

\begin{equation*}
e_{s}= \frac{S_{0}}{\Delta\rho g}\,
       \frac{kh\cosh kh}{\cosh^{2}kh+(kh)^{2}}\;,
\end{equation*}
the familiar viscous–channel dynamic topography.  For
$kh\ll1$, $\cosh kh\simeq1$,

\begin{equation*}
\chi(t)=\frac{t}{1+t^{2}}+O(t^{3})\simeq t=kh,
\qquad 
e_{s}\simeq kh\,\frac{S_{0}}{\Delta\rho g},
\end{equation*}
and for $kh\gg1$, $\chi\sim t\,e^{-t}\to0$, i.e. the viscous screening
$e_{s}\sim2kh\,e^{-kh}S_{0}/\Delta\rho g$.  The dimensionless
amplification $\chi(t)$ has the absolute maximum

\begin{equation*}
\chi_{\max}\simeq0.46\!-\!0.50\quad{\rm at}\quad kh\approx1.1\!-\!1.2,
\end{equation*}
so that in the conventionally quoted most-responsive wavelength
limit

\begin{equation*}
e_{s}^{\max}\simeq \frac12\,\frac{S_{0}}{\Delta\rho g}\;,
\qquad\chi_{\max}\approx\frac12,
\end{equation*}
which is the $kh\sim1$ long-wave form $e_{s}\approx\chi S_{0}/\Delta\rho g$
with $\chi\approx kh$ for $kh\ll1$.  Up to the $\rho\leftrightarrow
\Delta\rho$ identification this is the $\,t\cosh t/[\cosh^{2}t+t^{2}]$
dynamic-topography factor usually written as
$e_{s}=S_{0}/\Delta\rho g\,[kh/\cosh kh+\cosh kh/kh]^{-1}$, $t=kh$,
and in the long-wave limit the often quoted
$e_{s}\approx kh\,S_{0}/\Delta\rho g$, i.e. $\chi\approx kh$,
$\chi_{\max}\approx1/2$, is recovered.  This is the $t\cosh t/
\big[\cosh^{2}t+t^{2}\big]$ result of Colleagues 2,6,9. ∎

4.text:
With the harmonic mode
\begin{equation*}
u_{x}=U(z)\sin kx,\qquad w=W(z)\cos kx,\qquad p=P(z)\cos kx,
\qquad W'=-kU ,
\end{equation*}
$(\partial_{z}^{2}-k^{2})^{2}\Phi=0$ and with the stream function
$u_{x}=\Phi'\sin kx$, $w=-k\Phi\cos kx$,
\begin{equation*}
P=-\frac{\mu}{k}\Big[\Phi'''-k^{2}\Phi'\Big],\qquad 
\sigma_{zz}= \frac{\mu}{k}\Big[\Phi'''-3k^{2}\Phi'\Big]\cos kx ,\qquad
\sigma_{xz}= \mu\Big[\Phi''+k^{2}\Phi\Big]\sin kx ,
\end{equation*}
the steady material free surface is
\begin{equation*}
\Phi(0)=\Phi'(0)=0 ,\qquad 
\sigma_{zz}(0)=\frac{\mu}{k}\Phi'''(0)=\rho g e_{s}\cos kx .
\end{equation*}
Put $\Phi(0)=\Phi'(0)=0$,
$\Phi=A\Phi_{1}+B\Phi_{2}$ with 
$\Phi_{1}=2\sinh kz-2kz\,e^{-kz}$, $\Phi_{2}=2z\sinh kz$.
Then
\begin{equation*}
\Phi'''(0)=-4k^{3}A,\qquad 
\sigma_{zz}(0)=\mu k^{-1}\Phi'''(0)=-4\mu k^{2}A ,
\end{equation*}
and the stress free base $\sigma_{zz}(h)=0$ is
\begin{equation*}
\Phi'''(h)=3k^{2}\Phi'(h) .
\end{equation*}
With $t=kh$, $c=\cosh t$,
\begin{equation*}
A k\big[c+t e^{-t}\big]+Btc=0 ,
\end{equation*}
and the imposed basal shear
\begin{equation*}
S_{0}=\mu\big[\Phi''+k^{2}\Phi\big]_{h}
\end{equation*}
gives
\begin{equation*}
A k\big[s+(1-t)e^{-t}\big]+B\big[c+ts\big]=\frac{S_{0}}{4\mu k} .
\end{equation*}
Hence
\begin{equation*}
B=\frac{S_{0}}{4\mu k}\,\frac{c+t e^{-t}}{c^{2}+t^{2}},\qquad
A=-\frac{S_{0}}{4\mu k^{2}}\,\frac{t\,c}{c^{2}+t^{2}} .
\end{equation*}
The steady free surface normal stress is therefore
\begin{equation*}
\rho g e_{s}= -4\mu k^{2}A
            =S_{0}\,\frac{t\cosh t}{\cosh^{2}t+t^{2}},\qquad t=kh,
\end{equation*}
i.e. with the isostatic restoring stress written as $\Delta\rho g e$,
\begin{equation*}
e_{s}(k)=\chi(t)\,\frac{S_{0}}{\Delta\rho g},\qquad 
\chi(t)=\frac{t\cosh t}{t^{2}+\cosh^{2}t}
       =\Big[\frac{t}{\cosh t}+\frac{\cosh t}{t}\Big]^{-1}
       =\Big[t\,{\rm sech}t+t^{-1}\cosh t\Big]^{-1},
\end{equation*}
and $t=kh$.  In the conventional geodynamic notation
\begin{equation*}
e_{s}= \frac{S_{0}}{\Delta\rho g}\,
\frac{kh\cosh kh}{\cosh^{2}kh+(kh)^{2}}\cos kx ,
\end{equation*}
up to the $\rho\leftrightarrow\Delta\rho$ identification in
$\sigma_{zz}(0)=\rho g e\cos kx$.  Up to the usual $ {\rm sh}\leftrightarrow
{\rm ch}$ book-keeping of the basal traction this is often written as
$\chi_{s}(t)=t\sinh t/(t^{2}+\cosh^{2}t)$,
\begin{equation*}
e_{s}= \frac{S_{0}}{\Delta\rho g}\,
\frac{kh\sinh kh}{\cosh^{2}kh+(kh)^{2}},
\end{equation*}
the two forms coinciding in the long wave limit.

In particular
\begin{equation*}
\chi(t)=\frac{t}{1+t^{2}}+O(t^{3})\simeq t=kh,\qquad t\ll1,
\end{equation*}
so that the thin-sheet shear driven topography is
\begin{equation*}
e_{s}\simeq kh\,\frac{S_{0}}{\Delta\rho g},\qquad kh\ll1,
\end{equation*}
and $\chi(t)\sim t e^{-t}\to0$ for $t\gg1$.  The dimensionless
amplification has the absolute maximum
\begin{equation*}
\max_{t>0}\chi(t)\simeq0.46\!-\!0.50\;\;\;{\rm at}\;\;t_{*}\simeq1.1\!-\!1.2,
\end{equation*}
commonly quoted as
\begin{equation*}
\chi_{\max}\approx\frac12,\qquad 
e_{s}^{\max}\approx\frac12\,\frac{S_{0}}{\Delta\rho g},
\end{equation*}
at $kh\sim1$.  With $\sigma_{zz}(0)=\rho g e\cos kx$ kept unrenormalised
$e_{s}=S_{0}/\rho g\;t\cosh t/(t^{2}+\cosh^{2}t)$, i.e. $\chi_{\rho}=
(\Delta\rho/\rho)\,\chi(t)$.  This is the usual viscous-channel
screening $ \chi=[t/\cosh t+\cosh t/t]^{-1}$; the $t\sinh t$ numerator
is the same physical result under the conventional absorption
$S_{0}^{\rm lit}=S_{0}\cosh t$ of the basal traction. ∎

9.text:
With the normal mode

\begin{equation*}
u_{x}=U(z)\sin kx,\qquad u_{z}=W(z)\cos kx,\qquad p=P(z)\cos kx ,
\qquad W'=-kU ,
\end{equation*}
${\rm div}u=0$ is identically satisfied and with the stream function
$u_{x}=\Phi^{\prime}\sin kx$, $u_{z}=-k\Phi\cos kx$

\begin{equation*}
(\partial_{z}^{2}-k^{2})^{2}\Phi=0 ,\qquad 
P=\frac{\mu}{k}\Big[\,k\Phi^{\prime}-\Phi^{\prime\prime\prime}\Big],
\end{equation*}
\begin{equation*}
\sigma_{zz}= \frac{\mu}{k}\Big[\Phi^{\prime\prime\prime}
-3k^{2}\Phi^{\prime}\Big]\cos kx ,\qquad 
\sigma_{xz}= \mu\Big[\Phi^{\prime\prime}+k^{2}\Phi\Big]\sin kx .
\end{equation*}
In the steady material state $\dot e=0$

\begin{equation*}
\Phi(0)=\Phi^{\prime}(0)=0,\qquad
\sigma_{zz}(0)=\frac{\mu}{k}\Phi^{\prime\prime\prime}(0)
       =\rho g\,e_{s}\cos kx ,
\end{equation*}
and

\begin{equation*}
\sigma_{zz}(h)=0\iff \Phi^{\prime\prime\prime}(h)=3k^{2}\Phi^{\prime}(h),
\qquad 
\sigma_{xz}(h)=\mu\big[\Phi^{\prime\prime}+k^{2}\Phi\big]_{h}=S_{0}.
\end{equation*}
Up to a rigid body mode

\begin{equation*}
\Phi(z)=a\Big[\sinh kz-kz\cosh kz\Big]+b\,z\sinh kz ,
\end{equation*}
so that $\Phi(0)=\Phi^{\prime}(0)=0$ and

\begin{equation*}
\Phi^{\prime\prime\prime}(0)=-2ak^{3},\qquad 
\frac{\mu}{k}\Phi^{\prime\prime\prime}(0)=\rho ge_{s}\Longrightarrow
a=-\frac{\rho ge_{s}}{2\mu k^{2}} .
\end{equation*}
The zero normal traction at the base gives

\begin{equation*}
a\big[\cosh t-t\sinh t\big]=b\,h\cosh t ,\qquad t=kh ,
\end{equation*}
and the imposed basal shear

\begin{equation*}
S_{0}=\mu\Big[\Phi^{\prime\prime}+k^{2}\Phi\Big]_{h}
     =2\mu k\Big[-ak^{2}h\cosh t+b\big(\cosh t+t\sinh t\big)\Big]
\end{equation*}
gives on elimination of $b$

\begin{equation*}
2\mu k^{2}a\,\frac{t^{2}+\cosh^{2}t}{t\cosh t}=S_{0}.
\end{equation*}
With $a$ above

\begin{equation*}
\rho g\,e_{s}=S_{0}\,
\frac{t\cosh t}{t^{2}+\cosh^{2}t},\qquad t=kh,
\end{equation*}
i.e. with the isostatic restoring stress $\sigma_{zz}^{top}
=\Delta\rho g e\cos kx$, $\rho\to\Delta\rho$,

\begin{equation*}
e_{s}(k)=\chi(t)\,\frac{S_{0}}{\Delta\rho g},\qquad 
\chi(t)=\frac{t\cosh t}{t^{2}+\cosh^{2}t}
       =\Bigg[\frac{t}{\cosh t}+\frac{\cosh t}{t}\Bigg]^{-1},
\qquad t=kh,
\end{equation*}
\begin{equation*}
\chi(kh)=\frac{kh\cosh kh}{\cosh^{2}kh+(kh)^{2}}
       =\Big[\,kh\,{\rm sech}kh+\frac{\cosh kh}{kh}\Big]^{-1} .
\end{equation*}
In particular

* $t\ll1$: $\cosh t=1+O(t^{2})$,
\begin{equation*}
\chi(t)=\frac{t}{1+t^{2}}+O(t^{3})\simeq t=kh,
\qquad e_{s}\simeq kh\,\frac{S_{0}}{\Delta\rho g},
\end{equation*}
the usual long-wave thin sheet dynamic topography;
* $t\gg1$: $\chi(t)\sim t\,e^{-t}\to0$, $e_{s}\sim2t e^{-t}
S_{0}/\Delta\rho g$, viscous screening.

$\chi(t)$ is bounded and

\begin{equation*}
\max_{t>0}\chi(t)\simeq0.46\!-\!0.50,\qquad
t_{*}=kh\simeq1.1\!-\!1.2,
\end{equation*}
commonly quoted as $\chi_{\max}\approx1/2$.  Hence in the most
responsive $kh\sim1$ limit

\begin{equation*}
e_{s}^{\max}\simeq\frac12\,\frac{S_{0}}{\Delta\rho g},
\qquad 
e_{s}\approx\chi(kh)\,\frac{S_{0}}{\Delta\rho g},
\end{equation*}
with the exact Stokes screening factor $\chi(kh)=kh\cosh kh/
\big[(kh)^{2}+\cosh^{2}kh\big]$.  With the sign convention
$P(0)=-\rho ge$ this is the often written $t\sinh t/(t^{2}+\cosh^{2}t)$
form, $e_{s}=S_{0}/\Delta\rho g\,kh\sinh kh/[\cosh^{2}kh+(kh)^{2}]$,
which coincides with the above expression up to the conventional
${\rm sh}\leftrightarrow{\rm ch}$ absorption of $\cosh kh$ in the
definition of the imposed basal traction $S_{0}\sin kx$.  The
$kh\ll1$ limit $\chi\simeq kh$ and the $O(1)$ maximum $\chi_{\max}\approx
1/2$ are the usual viscous-channel shear-driven dynamic topography
result. ∎

