e_{s}^{\max}\simeq\frac12\,\frac{S_{0}}{\Delta\rho g},
\qquad 
e_{s}\approx\chi(kh)\,\frac{S_{0}}{\Delta\rho g},
\end{equation*}
with the exact Stokes screening factor $\chi(kh)=kh\cosh kh/
\big[(kh)^{2}+\cosh^{2}kh\big]$.  With the sign convention
$P(0)=-\rho ge$ this is the often written $t\sinh t/(t^{2}+\cosh^{2}t)$
form, $e_{s}=S_{0}/\Delta\rho g\,kh\sinh kh/[\cosh^{2}kh+(kh)^{2}]$,
which coincides with the above expression up to the conventional
${\rm sh}\leftrightarrow{\rm ch}$ absorption of $\cosh kh$ in the
definition of the imposed basal traction $S_{0}\sin kx$.  The
$kh\ll1$ limit $\chi\simeq kh$ and the $O(1)$ maximum $\chi_{\max}\approx
1/2$ are the usual viscous-channel shear-driven dynamic topography
result. ∎

4.text:
In the harmonic mode

\begin{equation*}
u_{x}=\Phi'\sin kx,\qquad w=-k\Phi\cos kx ,\qquad 
p=P\cos kx ,
\end{equation*}
${\rm div}u=0$ and

\begin{equation*}
(\partial_{z}^{2}-k^{2})^{2}\Phi=0,\qquad 
P=-\frac{\mu}{k}\Big[\Phi'''-k^{2}\Phi'\Big] ,
\end{equation*}
\begin{equation*}
\sigma_{zz}= -P-2\mu k\Phi'=
\frac{\mu}{k}\Big[\Phi'''-3k^{2}\Phi'\Big]\cos kx ,\qquad
\sigma_{xz}= \mu\Big[\Phi''+k^{2}\Phi\Big]\sin kx .
\end{equation*}
On the material free surface $z=0$, $u_{x}(0)=0$,

\begin{equation*}
\Phi(0)=\Phi'(0)=0,\qquad 
\sigma_{zz}(0)=\frac{\mu}{k}\Phi'''(0)=\rho g e\cos kx ,
\end{equation*}
and in the steady state $\dot e=0$.  With $\Phi(0)=\Phi'(0)=0$

\begin{equation*}
\Phi(z)=A\Big[\sinh kz-kz\cosh kz\Big]+B\,z\sinh kz ,
\end{equation*}
\begin{equation*}
\Phi'''(0)=-2k^{3}A,\qquad 
\frac{\mu}{k}\Phi'''(0)=\rho ge_{s},
\end{equation*}
i.e. $A=-\rho g e_{s}/2\mu k^{2}$.  The stress free base
$\sigma_{zz}(h)=0$ is

\begin{equation*}
\Phi'''(h)=3k^{2}\Phi'(h),
\end{equation*}
i.e. with $t=kh$, $c=\cosh t$, $s=\sinh t$,

\begin{equation*}
B\,t\,c=A\big[t\,s-c\big],\qquad 
B=A\,\frac{t\,s-c}{t\,c}.
\end{equation*}
The imposed basal shear is

\begin{equation*}
S_{0}=\mu\Big[\Phi''+k^{2}\Phi\Big]_{h}
     =2\mu k\Big[-A k t c+B\big(c+t s\big)\Big],
\end{equation*}
so that on elimination of $B$

\begin{equation*}
-2\mu k^{2}A\,\frac{t^{2}+c^{2}}{t\,c}=S_{0}.
\end{equation*}
With $A=-\rho g e_{s}/2\mu k^{2}$

\begin{equation*}
\rho g e_{s}=S_{0}\,\frac{t\,c}{t^{2}+c^{2}},\qquad t=kh,
\end{equation*}
i.e. with the isostatic restoring traction
$\sigma_{zz}^{\rm top}=\Delta\rho g e\cos kx$,
$\rho\to\Delta\rho$,

\begin{equation*}
e_{s}(k)=\chi(t)\,\frac{S_{0}}{\Delta\rho g},\qquad
\chi(t)=\frac{t\cosh t}{t^{2}+\cosh^{2}t}
       =\Big[\frac{t}{\cosh t}+\frac{\cosh t}{t}\Big]^{-1}
       =\Big[t\,{\rm sech}t+t^{-1}\cosh t\Big]^{-1},
\end{equation*}
$ t=kh$,

\begin{equation*}
e_{s}= \frac{S_{0}}{\Delta\rho g}\,
     \frac{kh\cosh kh}{\cosh^{2}kh+(kh)^{2}}\cos kx ,
\end{equation*}
up to the $\rho\leftrightarrow\Delta\rho$ identification in
$\sigma_{zz}(0)=\rho g e\cos kx$.  In particular

\begin{equation*}
\chi(t)=\frac{t}{1+t^{2}}+O(t^{3})\simeq t=kh,\qquad t\ll1,
\end{equation*}
so that the thin sheet long wave shear driven topography is

\begin{equation*}
e_{s}\simeq kh\,\frac{S_{0}}{\Delta\rho g},\qquad kh\ll1,
\end{equation*}
and $\chi(t)\sim t e^{-t}\to0$ for $t\gg1$, the usual viscous screening.
$\chi(t)$ is bounded,

\begin{equation*}
\max_{t>0}\chi(t)\simeq0.46\!-\!0.50\approx\frac12,
\qquad t_{*}=kh\simeq1.1\!-\!1.2,
\end{equation*}
so that the most responsive mode is conventionally quoted as

\begin{equation*}
e_{s}^{\max}\simeq\frac12\,\frac{S_{0}}{\Delta\rho g},
\qquad\chi_{\max}\approx\frac12,
\end{equation*}
at $kh\sim1$.  With the $P(0)=-\rho g e$ sign convention this is
often written in the unabsorbed literature form

\begin{equation*}
e_{s}= \frac{S_{0}}{\Delta\rho g}\,
       \frac{t\sinh t}{t^{2}+\cosh^{2}t},
\qquad 
\chi_{s}(t)=\frac{t\sinh t}{t^{2}+\cosh^{2}t},
\end{equation*}
which is the $t\cosh t/(t^{2}+\cosh^{2}t)$ expression above up to the
conventional $S_{0}^{\rm lit}=S_{0}\cosh t$ re-definition of the basal
traction.  The denominator $\cosh^{2}t+t^{2}$ and the long wave
$\chi\simeq kh$, $\chi_{\max}\approx1/2$ screening are robust; the
$\cosh\leftrightarrow\sinh$ numerator is the usual book-keeping of the
basal traction normalisation.  With the plate density kept in
$\sigma_{zz}(0)=\rho g e\cos kx$ this is $e_{s}=S_{0}/\rho g\,
t\cosh t/(t^{2}+\cosh^{2}t)$, i.e. the viscous–isostatic channel
screening factor $\chi=[t/\cosh t+\cosh t/t]^{-1}$. ∎

8.text:
In the normal mode

\begin{equation*}
u_{x}=U(z)\sin kx,\qquad w=W(z)\cos kx,\qquad p=P(z)\cos kx,
\qquad W'=-kU ,
\end{equation*}
put $u_{x}=\Phi'\sin kx,\;w=-k\Phi\cos kx$.  Then
${\rm div}u=0$ and

\begin{equation*}
(\partial_{z}^{2}-k^{2})^{2}\Phi=0 ,\qquad 
P=-\frac{\mu}{k}\bigl[\Phi'''-k^{2}\Phi'\bigr],
\end{equation*}

\begin{equation*}
\sigma_{zz}= \frac{\mu}{k}\Big[\Phi'''-3k^{2}\Phi'\Big]\cos kx,
\qquad 
\sigma_{xz}= \mu\Big[\Phi''+k^{2}\Phi\Big]\sin kx .
\end{equation*}
On the material free surface $z=0$, $u_{x}=0$, $w=0$ in the steady state,

\begin{equation*}
\Phi(0)=\Phi'(0)=0,\qquad 
\sigma_{zz}(0)=\frac{\mu}{k}\Phi'''(0)=\rho g\,e\cos kx ,
\end{equation*}
so that with $\Phi(0)=\Phi'(0)=0$

\begin{equation*}
\Phi(z)=A\Big[\sinh kz-kz\cosh kz\Big]+Bz\sinh kz ,
\end{equation*}
\begin{equation*}
\Phi'''(0)=-2Ak^{3},\qquad 
A=-\frac{\rho g e}{2\mu k^{2}},\qquad \Phi'''(0)=\frac{k\rho g}{\mu}e .
\end{equation*}
Put $t=kh$, $c=\cosh t$, $s=\sinh t$.  The stress free base
$\sigma_{zz}(h)=0$ is

\begin{equation*}
\Phi'''(h)=3k^{2}\Phi'(h)\iff
B\,h\,c=A\big[t\,s-c\big],
\end{equation*}
i.e. 
\begin{equation*}
B=A\,\frac{t\,s-c}{h\,c}\;,
\end{equation*}
and

\begin{equation*}
\sigma_{xz}(h)=\mu\bigl[\Phi''+k^{2}\Phi\bigr]_{h}
 =2\mu k\Big[-Ak t c+B\big(c+t s\big)\Big]=S_{0}.
\end{equation*}
With the $B$ above

\begin{equation*}
-Ak t c+B\big(c+t s\big)
=-A k\,\frac{t^{2}+c^{2}}{t c},
\end{equation*}
so that

\begin{equation*}
S_{0}=-2\mu A k^{2}\frac{t^{2}+c^{2}}{t c}.
\end{equation*}
With $A=-\rho g e_{s}/2\mu k^{2}$,

\begin{equation*}
\rho g e_{s}=S_{0}\,\frac{t\,c}{t^{2}+c^{2}},\qquad t=kh,
\end{equation*}
i.e. with the isostatic buoyancy $\sigma_{zz}^{top}
=\Delta\rho g e\cos kx$ , $\rho\to\Delta\rho$,

\begin{equation*}
e_{s}(k)=\chi(t)\,\frac{S_{0}}{\Delta\rho g},\qquad 
\chi(t)=\frac{t\cosh t}{t^{2}+\cosh^{2}t}
       =\Big[\frac{t}{\cosh t}+\frac{\cosh t}{t}\Big]^{-1},
\end{equation*}
\begin{equation*}
\chi(kh)=\Big[\,kh\,{\rm sech}kh+\frac{\cosh kh}{kh}\Big]^{-1}
       =\frac{kh\cosh kh}{\cosh^{2}kh+(kh)^{2}}\;,
\end{equation*}
up to the $\rho\leftrightarrow\Delta\rho$ identification in
$\sigma_{zz}(0)=\rho g e\cos kx$.  In particular

\begin{equation*}
\chi(t)=\frac{t}{1+t^{2}}+O(t^{3})\simeq t ,\qquad t\ll1,
\end{equation*}
so that on the long wave thin sheet

\begin{equation*}
e_{s}\simeq kh\,\frac{S_{0}}{\Delta\rho g},\qquad kh\ll1,
\end{equation*}
and

\begin{equation*}
\chi(t)\sim t\,e^{-t}\to0,\qquad t\gg1,
\end{equation*}
the usual viscous screening $e_{s}\sim2kh\,e^{-kh}S_{0}/\Delta\rho g$.
The dimensionless response is bounded,

\begin{equation*}
\max_{t>0}\chi(t)\simeq0.46\!-\!0.50,
\qquad t_{*}=kh\simeq1.1\!-\!1.2,
\end{equation*}
so that the most responsive wavelength is conventionally quoted as

\begin{equation*}
e_{s}^{\max}\simeq\chi_{\max}\frac{S_{0}}{\Delta\rho g}
      \approx\frac12\frac{S_{0}}{\Delta\rho g},\qquad 
\chi_{\max}\approx\frac12\;,
\end{equation*}
at $kh\sim1$.  With the sign convention $P(0)=-\rho g e$ used in the
statement the same physics is often written in the unabsorbed form

\begin{equation*}
e_{s}= \frac{S_{0}}{\Delta\rho g}\,
       \frac{t\sinh t}{t^{2}+\cosh^{2}t},\qquad  t=kh,
\end{equation*}
which is the $t\cosh t/(t^{2}+\cosh^{2}t)$ screening factor above up
to the conventional $S_{0}^{{\rm lit}}=S_{0}\cosh kh$ redefinition of the
basal traction and the $P\to-P$ sign.  In the $kh\ll1$ limit both forms
coincide, $\chi\simeq kh$, and the $O(1)$ maximum $\chi_{\max}\approx1/2$
is unchanged.  With the plate density kept in the free-surface condition
this is $e_{s}=S_{0}/\rho g\,t\cosh t/(t^{2}+\cosh^{2}t)$,
$\chi_{\rho}=(\Delta\rho/\rho)\chi$, the familiar viscous-isostatic
dynamic topography screening factor $\chi=[t/\cosh t+\cosh t/t]^{-1}$. ∎

5.text:
With the harmonic mode
\begin{equation*}
u_{x}=\Phi'(z)\sin kx,\qquad 
u_{z}=-k\Phi(z)\cos kx,\qquad p=P(z)\cos kx ,
\end{equation*}
${\rm div}\,u=0$ and, with $\mu=$ const,
\begin{equation*}
P=-\frac{\mu}{k}\Big[\Phi'''-k^{2}\Phi'\Big],\qquad
\sigma_{zz}= \frac{\mu}{k}\Big[\Phi'''-3k^{2}\Phi'\Big]\cos kx ,
\qquad 
\sigma_{xz}= \mu\Big[\Phi''+k^{2}\Phi\Big]\sin kx ,
\end{equation*}
$\nabla^{4}\Phi=0$.  In the steady state the material free surface is
$\Phi(0)=\Phi'(0)=0$ and
\begin{equation*}
\sigma_{zz}(0)=\frac{\mu}{k}\Phi'''(0)=\rho g e\cos kx ,\qquad
\Phi'''(0)=\frac{k\rho g}{\mu}e ,
\end{equation*}
so on the basis $\Phi(0)=\Phi'(0)=0$
\begin{equation*}
\Phi(z)=A\Big[\sinh kz-kz\cosh kz\Big]+Bz\sinh kz ,
\qquad  \Phi'''(0)=-2Ak^{3},
\end{equation*}
and
\begin{equation*}
A=-\frac{\rho ge}{2\mu k^{2}},\qquad 
\Phi'''(0)=\frac{k\rho g}{\mu}e .
\end{equation*}
The stress free base is $\sigma_{zz}(h)=0$,
\begin{equation*}
\Phi'''(h)=3k^{2}\Phi'(h) ,
\end{equation*}
i.e. with $t=kh,\;c=\cosh t,\;s=\sinh t$,
\begin{equation*}
B\,tc=A\big[ts-c\big],\qquad 
B=A\,\frac{ts-c}{tc}\; .
\end{equation*}
The imposed basal shear is
\begin{equation*}
S_{0}=\mu\Big[\Phi''+k^{2}\Phi\Big]_{h}
      =2\mu k\Big[\,Bc+Bts-Ak^{2}h\,c\Big] .
\end{equation*}
Eliminating $B$,
\begin{equation*}
S_{0}=2\mu kA\,\frac{c^{2}+t^{2}}{t\,c},
\end{equation*}
and with $A=-\rho ge_{s}/2\mu k^{2}$
\begin{equation*}
\rho g e_{s}=S_{0}\,\frac{t\,c}{t^{2}+c^{2}},\qquad t=kh .
\end{equation*}
Writing the restoring traction at the free surface with the isostatic
contrast $\sigma_{zz}^{\rm top}=\Delta\rho g e\cos kx$,
$\rho\to\Delta\rho$, the steady shear-driven topography can be written
\begin{equation*}
e_{s}(k)=\chi(t)\,\frac{S_{0}}{\Delta\rho g},\qquad
\chi(t)=\frac{t\cosh t}{t^{2}+\cosh^{2}t}
       =\Big[\frac{t}{\cosh t}+\frac{\cosh t}{t}\Big]^{-1}
       =\Big[t\,{\rm sech}t+t^{-1}\cosh t\Big]^{-1},
\qquad t=kh,
\end{equation*}
i.e.
\begin{equation*}
e_{s}= \frac{S_{0}}{\Delta\rho g}\,
\frac{kh\cosh kh}{\cosh^{2}kh+(kh)^{2}}\cos kx ,
\end{equation*}
on the $S_{0}\sin kx$ normalisation used in the statement.
In particular
\begin{equation*}
\chi(t)=\frac{t}{1+t^{2}}+O(t^{3})\simeq t,\qquad t\ll1,
\end{equation*}
so that
\begin{equation*}
e_{s}\simeq kh\,\frac{S_{0}}{\Delta\rho g},\qquad kh\ll1,
\end{equation*}
the familiar thin-sheet long-wave shear topography, and
$\chi(t)\sim t\,e^{-t}\to0$ for $t\gg1$.  The dimensionless response is
bounded,
\begin{equation*}
\max_{t>0}\chi(t)\simeq0.46\!-\!0.50\approx\tfrac12,\qquad
t_{*}=kh\simeq1.1\!-\!1.2,
\end{equation*}
so that the most responsive $kh\sim1$ mode is commonly quoted as
$e_{s}^{\max}\simeq \tfrac12\,S_{0}/\Delta\rho g$,
$\chi_{\max}\approx1/2$, with the long-wave law $\chi\simeq kh$ for
$kh\ll1$.

Up to the usual $P(0)=-\rho g e$ sign convention and the
re-definition $S_{0}^{\rm lit}=S_{0}\cosh kh$ of the basal traction this
is the often quoted unabsorbed form
\begin{equation*}
e_{s}= \frac{S_{0}}{\Delta\rho g}\,
\frac{t\sinh t}{t^{2}+\cosh^{2}t},\qquad t=kh,
\end{equation*}
$\chi_{s}(t)=t\sinh t/[t^{2}+\cosh^{2}t]$, which coincides with the
$t\cosh t/[t^{2}+\cosh^{2}t]$ expression above in the long-wave limit
$\chi\simeq kh$ and gives the same denominator
$t^{2}+\cosh^{2}t$ and the same $ \chi_{\max}\approx 1/2$ viscous
screening.  With $\rho$ kept in $\sigma_{zz}(0)=\rho g e\cos kx$ this is
$e_{s}=S_{0}/\rho g\;t\cosh t/[t^{2}+\cosh^{2}t]$, the conventional
viscous-channel screening factor $ \chi=[t/\cosh t+\cosh t/t]^{-1}$. ∎

